/**
 * Cart total condition for gating a `cart_discount` action. The action is applied only when the cart total (or the total of a filtered subset of items) meets the threshold. When the condition passes, the discount applies to all cart items.
 * **Placement rules:**
 * - Valid as the top-level condition strategy. - Valid as a direct child of `and`/`or` (when all siblings are also cart-level). - **Not valid** inside item-level condition children.
 * **Children (optional):** item-level strategies that filter which items count toward the total check. For example, a `cart_total(gte 10000)` with an `item_identifier` child means "apply this action if the total of matching items is at least $100". The discount itself still applies to all cart items once the gate passes.
 */
export const zCartTotalCondition = z
  .object({
    strategy: z.literal("cart_total").register(z.globalRegistry, {
      description: "Cart total condition strategy",
    }),
    operator: z
      .enum(["gte", "gt", "lte", "lt", "eq", "range"])
      .register(z.globalRegistry, {
        description: "Comparison operator for the cart total threshold.",
      }),
    args: z.union([zCartTotalArg, zCartTotalRangeArg]),
    children: z
      .array(zBaseCondition)
      .register(z.globalRegistry, {
        description:
          "Optional item-level conditions that filter which items count toward the total threshold check. Only leaf item strategies are allowed here — no `and`/`or` combinators and no nested `cart_total`.",
      })
      .optional(),
  })
  .register(z.globalRegistry, {
    description:
      'Cart total condition for gating a `cart_discount` action. The action is applied only when the cart total (or the total of a filtered subset of items) meets the threshold. When the condition passes, the discount applies to all cart items.\n**Placement rules:**\n- Valid as the top-level condition strategy. - Valid as a direct child of `and`/`or` (when all siblings are also cart-level). - **Not valid** inside item-level condition children.\n**Children (optional):** item-level strategies that filter which items count toward the total check. For example, a `cart_total(gte 10000)` with an `item_identifier` child means "apply this action if the total of matching items is at least $100". The discount itself still applies to all cart items once the gate passes.',
  })

/**
 * Custom attribute-based condition for targeting cart items by their custom attributes. Allows complex filtering based on item-level custom metadata.
 */
export const zCartItemCustomAttributeCondition = z
  .object({
    strategy: z.literal("item_custom_attribute").register(z.globalRegistry, {
      description: "Strategy for matching cart items by custom attributes",
    }),
    operator: z
      .enum(["in", "nin", "eq", "gt", "lt", "gte", "lte"])
      .register(z.globalRegistry, {
        description: "Operator for comparing custom attribute values",
      })
      .optional(),
    args: z
      .tuple([
        z
          .string()
          .min(1)
          .max(255)
          .regex(/^[A-Za-z0-9_-]{1,255}$/),
        z.enum(["string", "boolean", "integer", "float"]),
        z.union([z.string(), z.boolean(), z.int(), z.number()]),
      ])
      .register(z.globalRegistry, {
        description:
          "Arguments for the cart item custom attribute condition. The structure depends on the operator:\n- For `in` and `nin`: [key, type, value1, value2, ...valueN] where N can be 1-20 values - For comparison operators (`eq`, `gt`, `lt`, `gte`, `lte`): [key, type, value] - exactly 3 arguments\n**Float with `in`/`nin`:** Matching uses exact equality. Floating-point representation can cause values that look equal (e.g. after arithmetic) to not match; use `gt`/`lt` for numeric ranges when possible.",
      })
      .optional(),
  })
  .register(z.globalRegistry, {
    description:
      "Custom attribute-based condition for targeting cart items by their custom attributes. Allows complex filtering based on item-level custom metadata.",
  })

/**
 * The condition that gates this action. When present, the action is applied only if the condition is satisfied.
 * **Valid top-level strategies:**
 * - `cart_total` — gates the action based on the cart total (or filtered item total).
 * Supported on `cart_discount` actions only.
 * - `and` / `or` — logical combinators. Children must all be the same level (all
 * cart-level or all item-level). `and`/`or` is only valid at the top level.
 * - Item-level strategies (`item_identifier`, `item_price`, `item_quantity`,
 * `item_category`, `item_attribute`, `item_custom_attribute`) — filter which
 * items the cart discount applies to.
 *
 * **Placement rules for `cart_total`:**
 * - Valid at the top level or as a direct child of `and`/`or` (all-cart siblings). - Not valid inside item-level condition children.
 */
export const zCondition = z.discriminatedUnion("strategy", [
  zAndCondition,
  zOrCondition,
  zCartTotalCondition,
  zItemIdentifierCondition,
  zItemPriceCondition,
  zItemQuantityCondition,
  zItemCategoryCondition,
  zItemAttributeCondition,
  zCartItemCustomAttributeCondition,
  zShippingTypeCondition,
  zItemsBundleCondition,
])

